"""Report the exact frozen first model and second model used by the linked UI."""
import json,html
import numpy as np
from train_purchase_model import OUTPUT,ITEMS
records=json.loads((OUTPUT/'purchase_model_dataset.json').read_text())
report=json.loads((OUTPUT/'purchase_model_report.json').read_text())
rows=[];all_error=0.;all_actual=0.;count=0
for item in ITEMS:
 cases={r['date']:r for r in records if r['item']==item and r['split']=='test'}
 actual=np.array([r['actual'] for r in cases.values()]);forecast=np.array([r['forecast'] for r in cases.values()])
 error=float(np.abs(actual-forecast).sum());total=float(actual.sum());n=actual.size
 rows.append({'item':item,'windows':len(cases),'days':n,'mae':error/n,'wape':100*error/total if total else None});all_error+=error;all_actual+=total;count+=n
metrics={'first_model_cutoff':'2014-12-31','source_sha256':report['source_sha256'],'forecast_horizon':7,'test':rows,'total':{'mae':all_error/count,'wape':100*all_error/all_actual,'unique_item_days':count},'purchase':report['metrics']['test']}
(OUTPUT/'workflow_report.json').write_text(json.dumps(metrics,indent=2),encoding='utf-8')
table=''.join(f'<tr><td>{r["item"]}</td><td>{r["windows"]}</td><td>{r["mae"]:.2f}</td><td>{r["wape"]:.2f}%</td></tr>' for r in rows)
totals=metrics['purchase']['real_sales_totals'];saving=100*(1-totals['ml2']['cost']/totals['baseline']['cost'])
purchase=''.join(f'<tr><td>{name}</td><td>{v["cost"]:,.2f}</td><td>{v["shortage"]:.0f}</td><td>{v["waste"]:.0f}</td><td>{v["remaining"]:.0f}</td></tr>' for key,name in [('ml2','AI ตัวที่ 2'),('baseline','วิธีพื้นฐาน'),('teacher','ค้นหาแผนจากคำทำนาย')] for v in [totals[key]])
page=f'''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ผลทดสอบระบบสอง AI</title><style>body{{font:16px Tahoma;line-height:1.9;background:#f5f3ff;color:#30313e;margin:20px}}main{{max-width:1050px;margin:auto}}section{{background:white;padding:24px;border-radius:14px;margin:20px 0}}table{{width:100%;border-collapse:collapse;white-space:nowrap}}td,th{{padding:10px;border-bottom:1px solid #eee;text-align:left}}.scroll{{overflow:auto}}</style><main><section><h1>ผลทดสอบของขั้นตอน 7 วัน → AI จัดซื้อ</h1><p>AI ตัวที่ 1: Linear Regression ฝึกถึง 31 ธ.ค. 2014 และใช้ค่าน้ำหนักนี้ร่วมกันทั้งสองหน้า ทำนายต่อเนื่อง 7 วันจากข้อมูลก่อนวันเริ่ม ไม่ใช้ยอดขายจริงระหว่าง 7 วันช่วยทำนาย วันทดลองบนเว็บเริ่ม 23 พ.ค. 2016 ยังไม่มียอดจริงให้ตรวจ</p><p>ทดสอบย้อนหลังช่วง ม.ค.–พ.ค. 2016 จำนวน 9 ช่วงต่อสินค้า × 5 สินค้า = 45 ช่วง หรือ 315 วันสินค้า ไม่มีช่วงซ้อนกัน ไม่นับยอดขายซ้ำจากเงื่อนไขจำลอง 4 แบบ คะแนนเป็นผลย้อนหลังจากข้อมูล M5 ที่เคยศึกษาแล้ว ไม่ใช่หลักฐานจากร้านใหม่</p><div class="scroll"><table><tr><th>สินค้า</th><th>ช่วง 7 วัน</th><th>MAE (หน่วย/วัน)</th><th>WAPE</th></tr>{table}</table></div><p>รวม MAE {metrics['total']['mae']:.2f} หน่วย/วัน · WAPE {metrics['total']['wape']:.2f}% ค่า MAE/WAPE ยิ่งต่ำยิ่งดี WAPE ไม่ใช่เปอร์เซ็นต์จำแนกถูก และไม่มีการรับรองว่าทุกสินค้าจะแม่นเกิน 80%</p></section><section><h2>AI ตัวที่ 2: Decision Tree Regression</h2><p>เรียนรู้จำนวนแพ็ก วันรอสั่ง และวิธีส่ง จากตัวค้นหาแผนบนยอดคาดการณ์ แบ่งตามวันเป็นฝึก 420 ตรวจสอบ 80 และทดสอบ 180 สถานการณ์ เงื่อนไขวันเดียวกันไม่ข้ามชุด การทดสอบใช้ยอดขายจริง M5 แต่สต็อก ต้นทุน อายุสินค้าและระยะทางเป็นสมมุติ</p><div class="scroll"><table><tr><th>วิธี</th><th>ต้นทุนรวมสมมุติ (บาท)</th><th>ขาด (หน่วย)</th><th>หมดอายุ (หน่วย)</th><th>เหลือ (หน่วย)</th></tr>{purchase}</table></div><p>AI ลดต้นทุนสมมุติเทียบวิธีพื้นฐาน {saving:.2f}% แต่ของหมดอายุมากกว่า แผนตรงกับตัวค้นหาทุกองค์ประกอบ {metrics['purchase']['exact_action_match_pct']:.2f}% ค่านี้ไม่ใช่ความแม่นยำยอดขาย</p><p>คิดต้นทุนซื้อเต็ม ค่าส่ง ค่าขาด และค่ากำจัด ไม่หักมูลค่าของเหลือสิ้นวัน 7 ระยะทางเปลี่ยนค่าขนส่ง ไม่เปลี่ยนเวลาส่ง ไม่มีการวางเส้นทางจริง</p></section><section><h2>ข้อสรุปสำหรับเอกสาร</h2><p>ระบบเป็นต้นแบบสนับสนุนการตัดสินใจจากยอดขายจริงและสถานการณ์สมมุติ โมเดลทั้งสองทำงานต่อกันด้วยคำทำนายชุดเดียวกัน ผลยังไม่ยืนยันการลดต้นทุนในร้านจริง ต้องเก็บสต็อก วันหมดอายุ ต้นทุนและข้อมูลรับของจริงเพิ่มก่อน</p><p>แหล่งยอดขาย selected_5_foods.csv · SHA256 {html.escape(report['source_sha256'])}</p></section></main></html>'''
(OUTPUT/'workflow_report.html').write_text(page,encoding='utf-8')
print(json.dumps(metrics['total']));print('Synthetic purchase savings:',saving)
